let pdfFile=null,selectedCompressionLevel="low";const elements={uploadZone:document.getElementById("upload-zone"),fileInput:document.getElementById("file-input"),pdfInfo:document.getElementById("pdf-info"),compressionSettings:document.getElementById("compression-settings"),compressionLevels:document.querySelectorAll(".level-option"),originalSize:document.getElementById("original-size"),compressedSize:document.getElementById("compressed-size"),compressBtn:document.getElementById("compress-btn"),progressContainer:document.getElementById("progress-container"),successMessage:document.getElementById("success-message"),errorMessage:document.getElementById("error-message"),downloadBtn:document.getElementById("download-btn"),fileName:document.getElementById("file-name"),fileSize:document.getElementById("file-size"),totalPages:document.getElementById("total-pages"),progressFill:document.getElementById("progress-fill"),progressText:document.getElementById("progress-text"),errorText:document.getElementById("error-text"),compressionPercentage:document.getElementById("compression-percentage"),originalSizeDisplay:document.getElementById("original-size-display"),compressedSizeDisplay:document.getElementById("compressed-size-display")};function init(){elements.uploadZone.addEventListener("click",()=>elements.fileInput.click()),elements.uploadZone.addEventListener("dragover",handleDragOver),elements.uploadZone.addEventListener("dragleave",handleDragLeave),elements.uploadZone.addEventListener("drop",handleDrop),elements.fileInput.addEventListener("change",handleFileSelect),elements.compressionLevels.forEach(e=>{e.addEventListener("click",()=>selectCompressionLevel(e.dataset.level))}),elements.compressBtn.addEventListener("click",compressPDF),elements.downloadBtn.addEventListener("click",downloadPDF)}function handleDragOver(e){e.preventDefault(),elements.uploadZone.classList.add("dragover")}function handleDragLeave(){elements.uploadZone.classList.remove("dragover")}function handleDrop(e){e.preventDefault(),elements.uploadZone.classList.remove("dragover");const s=e.dataTransfer.files;s.length>0&&handleFile(s[0])}function handleFileSelect(e){const s=e.target.files[0];s&&handleFile(s)}function handleFile(e){"application/pdf"===e.type?e.size>52428800?showError("File size must be less than 50MB."):(pdfFile=e,elements.uploadZone.style.display="none",showPDFInfo(e),calculateEstimatedSize(e.size),loadPDFPages(e)):showError("Please select a valid PDF file.")}async function loadPDFPages(e){try{const s=await e.arrayBuffer(),n=(await PDFLib.PDFDocument.load(s)).getPageCount();elements.totalPages.textContent=n}catch(e){console.error("Error loading PDF pages:",e),elements.totalPages.textContent="N/A"}}function showPDFInfo(e){elements.fileName.textContent=e.name,elements.fileSize.textContent=(e.size/1024/1024).toFixed(2)+" MB",elements.totalPages.textContent="Calculating...",elements.pdfInfo.style.display="block",elements.compressionSettings.style.display="block"}function calculateEstimatedSize(e){const s=e*(1-{low:.15,medium:.4,high:.6}[selectedCompressionLevel]);elements.originalSize.textContent=(e/1024/1024).toFixed(2)+" MB",elements.compressedSize.textContent=(s/1024/1024).toFixed(2)+" MB"}function selectCompressionLevel(e){selectedCompressionLevel=e,elements.compressionLevels.forEach(e=>{e.classList.remove("selected")}),document.querySelector(`[data-level="${e}"]`).classList.add("selected"),pdfFile&&calculateEstimatedSize(pdfFile.size)}async function compressPDF(){if(pdfFile)try{showProgress("Compressing PDF...");const e=new FormData;e.append("file",pdfFile),e.append("level",selectedCompressionLevel);const s=await fetch("https://pdfindi-backend.onrender.com/api/compress-pdf",{method:"POST",body:e});if(!s.ok)throw new Error("Failed to compress PDF");const n=await s.json();console.log("✅Backend response received:",n),console.log("Compression ratio:",n.compressionRatio),console.log("Base64 data length:",n.base64?.length),hideProgress(),showSuccess(n.base64,n.filename,n.compressionRatio)}catch(e){hideProgress(),showError("Failed to compress PDF. Please try again."),console.error("Compression error:",e)}else showError("Please select a PDF file first.")}function downloadPDF(){console.log("📥 Download button clicked"),console.log("Download URL:",elements.successMessage.dataset.downloadUrl),console.log("Filename:",elements.successMessage.dataset.filename);const e=document.createElement("a");e.href=elements.successMessage.dataset.downloadUrl,e.download=elements.successMessage.dataset.filename||"compressed-pdf.pdf",console.log("📎 Triggering download..."),e.click(),setTimeout(()=>{window.URL.revokeObjectURL(e.href),console.log("🧹 Cleaned up download URL")},1e3)}function showProgress(e){elements.progressContainer.style.display="block",elements.progressText.textContent=e,elements.progressFill.style.animation="indeterminate 1.5s infinite",elements.compressionSettings.style.display="none",elements.pdfInfo.style.display="none"}function hideProgress(){elements.progressContainer.style.display="none",elements.progressFill.style.animation="none"}function showSuccess(e,s,n){try{console.log("🎯 showSuccess called with:",{base64Data:e?.length,filename:s,compressionRatio:n}),elements.successMessage.innerHTML=`\n                    <h4>✅Compression Complete!</h4>\n                    <p>Your PDF has been compressed by <span id="compression-percentage">${Math.round(parseFloat(n))}</span>%!</p>\n                    <p>Original: <span id="original-size-display">${elements.originalSize.textContent}</span> → Compressed: <span id="compressed-size-display">${elements.compressedSize.textContent}</span></p>\n                    <button onclick="downloadPDF()" class="btn btn-primary" style="margin-top: 1rem;">\n                        <span>📥</span> Download Compressed PDF\n                    </button>\n                    <button onclick="resetTool()" class="btn" style="margin-top: 1rem; margin-left: 1rem; background: #6c757d;">\n                        <span>🔄</span> Compress Another PDF\n                    </button>\n                `,console.log("📝 Success message HTML set"),console.log("🔄 Converting base64 to blob...");const t=atob(e);console.log("✅Base64 decoded, length:",t.length);const o=new Array(t.length);for(let e=0;e<t.length;e++)o[e]=t.charCodeAt(e);const l=new Uint8Array(o),a=new Blob([l],{type:"application/pdf"}),r=window.URL.createObjectURL(a);elements.successMessage.dataset.downloadUrl=r,elements.successMessage.dataset.filename=s,elements.successMessage.style.display="block",elements.errorMessage.style.display="none",console.log("✅Success message should now be visible!"),console.log("Success message element:",elements.successMessage),console.log("Success message display style:",elements.successMessage.style.display)}catch(e){console.error("Error in showSuccess:",e),showError("Failed to process compressed PDF for download.")}}function showError(e){elements.errorMessage.style.display="block",elements.errorText.textContent=e,elements.successMessage.style.display="none"}function resetTool(){pdfFile=null,selectedCompressionLevel="low",elements.fileInput.value="",elements.uploadZone.style.display="block",elements.pdfInfo.style.display="none",elements.compressionSettings.style.display="none",elements.successMessage.style.display="none",elements.errorMessage.style.display="none",elements.progressContainer.style.display="none",elements.compressionLevels.forEach(e=>{e.classList.remove("selected")}),document.querySelector('[data-level="low"]').classList.add("selected"),console.log("🔄 Tool reset completed")}document.addEventListener("DOMContentLoaded",init);